 * Parses the build graph format read from standard input.
 */

const NAME_PATTERN = /^[A-Za-z0-9_.-]+$/
const COST_PATTERN = /^\d+$/

function isValidName(name) {
  return NAME_PATTERN.test(name)
}

/**
 * Parses `input` into a Map from task name to { cost, deps, line }, where
 * `deps` is an array of dependency names (each appearing once). Throws an
 * Error whose message is the text that follows "error: " on failure.
