export function parseGraph(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map()
  const edges = [] // { subject, dep, line } in the order dep lines are read
  const referenced = [] // names used by dep lines, in input order

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) throw new Error(`line ${lineNo}: expected task <name> <cost>`)
      const [, name, costText] = words
      if (!isValidName(name)) throw new Error(`line ${lineNo}: invalid task name ${name}`)
      if (!COST_PATTERN.test(costText)) throw new Error(`line ${lineNo}: cost must be a non-negative integer`)
      if (tasks.has(name)) throw new Error(`line ${lineNo}: task ${name} is declared twice`)
      tasks.set(name, { cost: parseInt(costText, 10), deps: [], line: lineNo })
    } else if (directive === 'dep') {
      if (words.length < 3) throw new Error(`line ${lineNo}: expected dep <name> <dependency>...`)
      const subject = words[1]
      const deps = words.slice(2)
      for (const name of [subject, ...deps]) {
        if (!isValidName(name)) throw new Error(`line ${lineNo}: invalid task name ${name}`)
      }
      referenced.push(subject, ...deps)
      for (const dep of deps) edges.push({ subject, dep, line: lineNo })
    } else {
      throw new Error(`line ${lineNo}: unknown directive ${directive}`)
    }
  }

  for (const name of referenced) {
    if (!tasks.has(name)) throw new Error(`unknown task ${name}`)
  }

  for (const { subject, dep } of edges) {
    const entry = tasks.get(subject)
    if (!entry.deps.includes(dep)) entry.deps.push(dep)
  }

  return tasks
}
"}

