{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-aiBCUh/src/graph.js","content":"/**
 * Cycle detection and the unlimited-worker schedule (start, finish, depth)
 * for a parsed build graph.
 */

/**
 * Returns the first cycle a depth-first search finds when it starts from
 * each task in ascending name order and walks each task's dependencies in
 * ascending name order, as an array of names from the re-entered task
 * through the search stack back to a repeat of that name. Returns null when
 * the graph has no cycle.
 */
export function findCycle(tasks) {
  const state = new Map() // name -> 'active' | 'done'
  const stack = []

  function visit(name) {
    state.set(name, 'active')
    stack.push(name)
    const deps = [...tasks.get(name).deps].sort()
    for (const dep of deps) {
      const status = state.get(dep)
      if (status === 'active') {
        const start = stack.indexOf(dep)
        return [...stack.slice(start), dep]
      }
      if (status !== 'done') {
        const found = visit(dep)
        if (found) return found
      }
    }
    stack.pop()
    state.set(name, 'done')
    return null
  }

  for (const name of [...tasks.keys()].sort()) {
    if (!state.has(name)) {
      const found = visit(name)
      if (found) return found
    }
  }
  return null
}

/**
 * Returns a Map from task name to { start, finish, depth } for the
 * unlimited-worker schedule: a task's start is the greatest finish among
 * its dependencies (0 when it has none), its finish is start + cost, and
 * its depth is one more than the greatest dependency depth (0 when it has
 * none). Assumes the graph has no cycle.
 */
export function computeSchedule(tasks) {
  const memo = new Map()

  function compute(name) {
    const cached = memo.get(name)
    if (cached) return cached
    const task = tasks.get(name)
    let maxFinish = 0
    let maxDepth = -1
    for (const dep of task.deps) {
      const depResult = compute(dep)
      if (depResult.finish > maxFinish) maxFinish = depResult.finish
      if (depResult.depth > maxDepth) maxDepth = depResult.depth
    }
    const start = task.deps.length > 0 ? maxFinish : 0
    const finish = start + task.cost
    const depth = task.deps.length > 0 ? maxDepth + 1 : 0
    const result = { start, finish, depth }
    memo.set(name, result)
    return result
  }

  for (const name of tasks.keys()) compute(name)
  return memo
}
"}

