function computePriorities(tasks) {
  const successors = new Map()
  for (const name of tasks.keys()) successors.set(name, [])
  for (const [name, task] of tasks) {
    for (const dep of task.deps) successors.get(dep).push(name)
  }

  const memo = new Map()
  function compute(name) {
    const cached = memo.get(name)
    if (cached !== undefined) return cached
    const task = tasks.get(name)
    let maxSuccessor = 0
    for (const successor of successors.get(name)) {
      const value = compute(successor)
      if (value > maxSuccessor) maxSuccessor = value
    }
    const priority = task.cost + maxSuccessor
    memo.set(name, priority)
    return priority
  }

  for (const name of tasks.keys()) compute(name)
  return memo
}

/**
 * Simulates the build graph on `workerCount` workers. Returns
 * { workerRuns, makespan }, where `workerRuns` is an array (one per worker,
 * in index order) of { name, start, finish } run in the order each worker
 * ran them, and `makespan` is the greatest finish time (0 when there are no
 * tasks).
 */
export function pack(tasks, workerCount) {
  const priority = computePriorities(tasks)
  const remaining = new Set(tasks.keys())
  const completed = new Map() // name -> finish
  const workers = Array.from({ length: workerCount }, () => ({ freeAt: 0, runs: [] }))
  let currentTime = 0

  while (remaining.size > 0) {
    let progressed = true
    while (progressed) {
      progressed = false

      let freeWorkerIndex = -1
      for (let i = 0; i < workers.length; i++) {
        if (workers[i].freeAt <= currentTime) {
          freeWorkerIndex = i
          break
        }
      }
      if (freeWorkerIndex === -1) break

      let best = null
      for (const name of remaining) {
        const task = tasks.get(name)
        const ready = task.deps.every((dep) => {
          const finish = completed.get(dep)
          return finish !== undefined && finish <= currentTime
        })
        if (!ready) continue
        if (best === null) {
          best = name
          continue
        }
        const bestPriority = priority.get(best)
        const namePriority = priority.get(name)
        if (namePriority > bestPriority || (namePriority === bestPriority && name < best)) best = name
      }
      if (best === null) break

      const task = tasks.get(best)
      const start = currentTime
      const finish = start + task.cost
      workers[freeWorkerIndex].freeAt = finish
      workers[freeWorkerIndex].runs.push({ name: best, start, finish })
      completed.set(best, finish)
      remaining.delete(best)
      progressed = true
    }

    if (remaining.size === 0) break

    let next = Infinity
    for (const worker of workers) {
      if (worker.freeAt > currentTime && worker.freeAt < next) next = worker.freeAt
    }
    currentTime = next
  }

  let makespan = 0
  for (const finish of completed.values()) {
    if (finish > makespan) makespan = finish
  }

  return { workerRuns: workers.map((worker) => worker.runs), makespan }
}
