  }
  const lines = []
  for (let depth = 0; depth <= maxDepth; depth++) {
    const names = (byDepth.get(depth) ?? []).sort()
    lines.push(`wave ${depth}: ${names.join(' ')}`)
  }
  let total = 0
  for (const result of schedule.values()) {
    if (result.finish > total) total = result.finish
  }
  lines.push(`total ${total}`)
  process.stdout.write(lines.join('\n') + '\n')
}

function runExplain(tasks, schedule) {
  const lines = []
  for (const name of [...tasks.keys()].sort()) {
    const result = schedule.get(name)
    lines.push(`${name} start=${result.start} finish=${result.finish} depth=${result.depth}`)
  }
  let total = 0
  for (const result of schedule.values()) {
    if (result.finish > total) total = result.finish
  }
  lines.push(`total ${total}`)
  process.stdout.write(lines.join('\n') + '\n')
}

function runPack(tasks, workerCount) {
  const { workerRuns, makespan } = pack(tasks, workerCount)
  const lines = workerRuns.map((runs, i) => {
    const parts = runs.map((run) => `${run.name}@${run.start}-${run.finish}`)
    return parts.length > 0 ? `worker ${i}: ${parts.join(' ')}` : `worker ${i}:`
  })
  lines.push(`makespan ${makespan}`)
  process.stdout.write(lines.join('\n') + '\n')
}

function main() {
  const argv = process.argv.slice(2)

  let mode = null
  let workerCount = null

  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    mode = argv[0]
  } else if (argv.length === 2 && argv[0] === 'pack') {
    mode = 'pack'
    if (!WORKERS_PATTERN.test(argv[1])) fail('workers must be a positive integer', 2)
    workerCount = parseInt(argv[1], 10)
  } else {
    fail(USAGE, 2)
  }

  const input = readStdin()

  let tasks
  try {
    tasks = parseGraph(input)
  } catch (err) {
    fail(err.message, 2)
    return
  }

  const cycle = findCycle(tasks)
  if (cycle) {
    process.stderr.write(`error: cycle: ${cycle.join(' -> ')}\n`)
    process.exit(3)
    return
  }

  if (mode === 'pack') {
    runPack(tasks, workerCount)
    return
  }

  const schedule = computeSchedule(tasks)
  if (mode === 'waves') runWaves(tasks, schedule)
  else runExplain(tasks, schedule)
}

